RED on main (P-21): 6/19 · 0/6 · 2/13 · 0/4 covered. """ from textual.widgets import Button, Input as _Input, Select as _Select
from tests.b97_fixtures import fx_project from tests.b97_probes import painted_rows
screen_ids = {"patch": "screen_patch", "check_editor": "screen_check_editor", "flow": "screen_flow", "flow_execution": "screen_flow_execution"}
async def _drive(): app = S19TuiApp(base_dir=tmp_path) async with app.run_test(size=(118, 54)) as pilot: await settle(pilot) await fx_project(app) screen = app.query_one(f"#{screen_ids[screen_key]}") labels = {}
def harvest(): for widget in screen.query("*"): if not isinstance(widget, (Button, _Input, _Select)): continue if not widget.display or widget.region.width == 0: continue if any(not a.display for a in widget.ancestors if hasattr(a, "display")): continue labels.setdefault(widget, set()).update(_fx_label(screen, widget))
await _drive_states(app, pilot, screen_key, harvest) bodies = [] chip_id = f"window_help_{screen_key}" for how in ("click", "enter"): chip = app.query_one(f"#{chip_id}") if how == "click": await pilot.click(f"#{chip_id}") else: chip.focus() await _poll(pilot, lambda: app.focused is chip and not chip.has_class("-active"), 120) await pilot.press("enter") opened = await _poll(pilot, lambda: type(app.screen).__name__ == "WindowHelpScreen", 120) if opened: await settle(pilot, 2) modal_text = "\n".join( str(w.render()) for w in app.screen.query("Static") if w.display ) bodies.append(modal_text) app.screen.dismiss() await _poll(pilot, lambda: type(app.screen).__name__ != "WindowHelpScreen") return labels, bodies
